10	func TestCompute(t *testing.T) {
11		inv := store.Invoice{
12			Lines:           []store.Line{{Description: "Seats", Quantity: 3, UnitAmount: 1500}, {Description: "Setup", Quantity: 1, UnitAmount: 999}},
13			DiscountPercent: 10,
14			TaxRateBP:       825,
15		}
16		got := Compute(inv)
17		// subtotal 5499; discount 549.9 -> 550; taxable 4949; tax 408.2925 -> 408
18		want := Totals{Subtotal: 5499, Discount: 550, Tax: 408, Total: 5357}
19		if got != want {
20			t.Fatalf("Compute = %+v, want %+v", got, want)
21		}
22	}
23	
24	func TestComputeWithoutDiscountOrTax(t *testing.T) {
25		got := Compute(store.Invoice{Lines: []store.Line{{Description: "x", Quantity: 2, UnitAmount: 250}}})
26		if got != (Totals{Subtotal: 500, Total: 500}) {
27			t.Fatalf("Compute = %+v", got)
28		}
29	}
30	
31	func TestAddInterval(t *testing.T) {
32		start := time.Date(2026, 3, 14, 9, 30, 0, 0, time.UTC)
33		if got := AddInterval(start, store.Monthly); !got.Equal(time.Date(2026, 4, 14, 9, 30, 0, 0, time.UTC)) {
34			t.Errorf("monthly: %v", got)
35		}
36		if got := AddInterval(start, store.Yearly); !got.Equal(time.Date(2027, 3, 14, 9, 30, 0, 0, time.UTC)) {
37			t.Errorf("yearly: %v", got)
38		}
39	}
