func TestTieredAmount(t *testing.T) {
	up := func(n int64) *int64 { return &n }
	tiers := []store.Tier{
		{UpTo: up(10), UnitAmount: 100},
		{UpTo: up(50), UnitAmount: 50, FlatAmount: 200},
		{UnitAmount: 25},
	}
	for _, c := range []struct {
		mode store.TiersMode
		q    int64
		want int64
	}{
		{store.Graduated, 0, 0},
		{store.Graduated, 5, 500},
		{store.Graduated, 10, 1000},
		{store.Graduated, 11, 1000 + 50 + 200},
		{store.Graduated, 50, 1000 + 40*50 + 200},
		{store.Graduated, 60, 1000 + 40*50 + 200 + 10*25},
		{store.Volume, 0, 0},
		{store.Volume, 5, 500},
		{store.Volume, 10, 1000},
		{store.Volume, 11, 11*50 + 200},
		{store.Volume, 50, 50*50 + 200},
		{store.Volume, 51, 51 * 25},
	} {
		if got := TieredAmount(tiers, c.mode, c.q); got != c.want {
			t.Errorf("TieredAmount(%s, %d) = %d, want %d", c.mode, c.q, got, c.want)
		}
	}
	if got := TieredAmount(nil, store.Graduated, 3); got != 0 {
		t.Errorf("no tiers = %d, want 0", got)
	}
}

