func TestTieredPlans(t *testing.T) {
	e := apitest.New(t)
	var p store.Plan
	e.MustDo(http.StatusCreated, "POST", "/v1/plans", e.Acme.Key, map[string]any{"name": "API calls", "currency": "USD", "interval": "month",
		"usage_type": "metered", "tiers_mode": "graduated", "tiers": []any{
			map[string]any{"up_to": 1000, "unit_amount": "0.10"},
			map[string]any{"up_to": 10000, "unit_amount": "0.05", "flat_amount": "5.00"},
			map[string]any{"up_to": nil, "unit_amount": "0.01"},
		}}, &p)
	if p.TiersMode != store.Graduated || len(p.Tiers) != 3 || p.Tiers[0].UpTo == nil || *p.Tiers[0].UpTo != 1000 || p.Tiers[0].UnitAmount != 10 ||
		p.Tiers[1].FlatAmount != 500 || p.Tiers[1].UnitAmount != 5 || p.Tiers[2].UpTo != nil || p.Tiers[2].UnitAmount != 1 {
		t.Fatalf("plan = %+v", p)
	}

	base := func() map[string]any {
		return map[string]any{"name": "API calls", "currency": "USD", "interval": "month", "usage_type": "metered", "tiers_mode": "volume",
			"tiers": []any{map[string]any{"up_to": 10, "unit_amount": "1"}, map[string]any{"unit_amount": "0.50"}}}
	}
	withTiers := func(tiers ...any) map[string]any {
		b := base()
		b["tiers"] = tiers
		return b
	}
	licensed := base()
	licensed["usage_type"], licensed["price"] = "licensed", "12.50"
	noMode := base()
	delete(noMode, "tiers_mode")
	for name, body := range map[string]map[string]any{
		"tiers on a licensed plan": licensed,
		"no tiers_mode":            noMode,
		"unknown tiers_mode":       func() map[string]any { b := base(); b["tiers_mode"] = "flat"; return b }(),
		"no tiers":                 withTiers([]any{}...),
