		"zero up_to":               withTiers(map[string]any{"up_to": 0, "unit_amount": "1"}, map[string]any{"unit_amount": "1"}),
		"null up_to midway":        withTiers(map[string]any{"up_to": nil, "unit_amount": "1"}, map[string]any{"unit_amount": "1"}),
		"last with up_to":          withTiers(map[string]any{"up_to": 10, "unit_amount": "1"}),
		"missing unit_amount":      withTiers(map[string]any{"up_to": 10}, map[string]any{"unit_amount": "1"}),
		"negative unit_amount":     withTiers(map[string]any{"up_to": 10, "unit_amount": "-1"}, map[string]any{"unit_amount": "1"}),
		"negative flat_amount":     withTiers(map[string]any{"up_to": 10, "unit_amount": "1", "flat_amount": "-1"}, map[string]any{"unit_amount": "1"}),
	} {
		if r := e.Do("POST", "/v1/plans", e.Acme.Key, body); r.Code != http.StatusUnprocessableEntity || r.Map(t)["error"] != "invalid_tiers" {
			t.Errorf("%s: %s", name, r)
		}
	}
	if r := e.Do("POST", "/v1/plans", e.Acme.Key, map[string]any{"name": "API calls", "currency": "USD", "interval": "month", "usage_type": "metered"}); r.Code != http.StatusUnprocessableEntity || r.Map(t)["error"] != "invalid_amount" {
		t.Fatalf("metered plan without price or tiers: %s", r)
	}
}

